// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public { c = new airPort(); }

    // fuzz parameters: from (address), v (uint256), single recipient tosAddr (address)
    // We use a single-recipient array to avoid needing to accumulate records in the helper.
    function testFuzz_property(address from, uint256 v, address tosAddr) public {
        // Keep domain wide but avoid zero-length recipient address and the zero address for caddress
        vm.assume(tosAddr != address(0));
        vm.assume(from != address(0));

        // Deploy a recording helper that implements the exact selector transferFrom(address,address,uint256)
        // and always returns true (to exercise the successful-call path).
        Recorder rec = new Recorder();

        // Build a single-element array of recipients in memory
        address[] memory tos = new address[](1);
        tos[0] = tosAddr;

        // Call c.transfer. The property we assert: when the external call succeeds, reference returns true.
        // Use try/catch to capture reverts (should not revert because Recorder returns true).
        bool ok;
        bool ret;
        try c.transfer(from, address(rec), tos, v) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // The Recorder recorded the last transferFrom call and whether it was called.
        // We constrain the admissible domain to cases where Recorder observed the call (i.e., c did call out).
        vm.assume(rec.called());

        // General rule: For every admissible input where the external transferFrom call occurred and succeeded,
        // the reference implementation returns true. We therefore assert that the call completed (not reverted)
        // and returned true.
        assertTrue(ok && ret);
    }
}

// Helper that matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
// and records that it was called. It returns true so the external call from C succeeds.
contract Recorder {
    bool public _called;
    address public fromArg;
    address public toArg;
    uint256 public vArg;

    // This function matches the selector the contract C encodes with abi.encodeWithSelector
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        _called = true;
        fromArg = from;
        toArg = to;
        vArg = v;
        return true;
    }

    function called() external view returns (bool) { return _called; }
}
